print("=== Build Transform Based on Gap Filling ===\n")

def transform_gap_filling(grid):
    """
    For each row in the bounding box of markers:
    - If markers span both edges (c_min and c_max both present), fill gaps between them with 2s
    - If row has NO markers within bbox, place 2s at c_min and c_max 
    - If row has markers at only one edge, place 2s at MISSING edge position and at that row's marker
    """
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    all_markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not all_markers:
        return [row[:] for row in grid]

    r_min, r_max = min(r for r, c in all_markers), max(r for r, c in all_markers)
    c_min, c_max = min(c for r, c in all_markers), max(c for r, c in all_markers)

    result = [row[:] for row in grid]

    for r in range(r_min, r_max + 1):
        row_markers = [c for c in range(c_min, c_max + 1) if grid[r][c] != bg]
        row_has_c_min = c_min in row_markers
        row_has_c_max = c_max in row_markers

        if not row_markers:
            # No markers: fill both edges
            if grid[r][c_min] == bg:
                result[r][c_min] = 2
            if grid[r][c_max] == bg:
                result[r][c_max] = 2
        elif row_has_c_min and row_has_c_max:
            # Has both edges: fill gaps
            for c in range(c_min + 1, c_max):
                if grid[r][c] == bg:
                    result[r][c] = 2
        elif row_has_c_min:
            # Only left edge: place 2 at c_max (filling up to right edge)
            if grid[r][c_max] == bg:
                result[r][c_max] = 2
            for c in range(c_max, c_min, -1):
                if grid[r][c] == bg:
                    result[r][c] = 2
        elif row_has_c_max:
            # Only right edge: place 2 at c_min
            if grid[r][c_min] == bg:
                result[r][c_min] = 2
            for c in range(c_min, c_max):
                if grid[r][c] == bg:
                    result[r][c] = 2

    return result

# Test
